extends "res://htd/htd_test.gd"

func _run_tests() -> void:
	var star := instantiate_scene("res://star.tscn")
	if not check("star_exists", star != null, "La scena star.tscn deve istanziarsi senza errori"):
		return
	var min_x: float = 9999.0
	var max_x: float = -9999.0
	for i in range(100):
		call_if_exists(star, "reset_star")
		var current_pos = get_prop(star, "position", Vector2.ZERO)
		if not check("y_at_start", is_equal_approx(current_pos.y, 80.0), "A ogni reset la stella deve tornare a Y = 80.0"):
			return
		if not check("x_in_bounds", current_pos.x >= 64.0 and current_pos.x <= 1088.0, "La coordinata X deve rimanere tra 64.0 e 1088.0"):
			return
		if current_pos.x < min_x:
			min_x = current_pos.x
		if current_pos.x > max_x:
			max_x = current_pos.x
	check("positions_vary", (max_x - min_x) > 300.0, "Su 100 tentativi le stelle non devono comparire tutte nella stessa colonna")
	star.set("position", Vector2(500.0, 500.0))
	var caught_close = call_if_exists(star, "is_caught", [Vector2(500.0, 540.0)], false)
	check("caught_close", caught_close == true, "A distanza di 40 pixel la stella deve risultare presa")
	var caught_edge = call_if_exists(star, "is_caught", [Vector2(500.0, 559.0)], false)
	check("caught_edge", caught_edge == true, "A distanza di 59 pixel la stella deve risultare presa")
	var caught_far = call_if_exists(star, "is_caught", [Vector2(500.0, 565.0)], true)
	check("caught_far", caught_far == false, "A distanza di 65 pixel la stella NON deve risultare presa")
